let loading,index;async function load(s){return index||(loading||(loading=fetch(s).then(t=>{if(!t.ok)throw Error("HTTP "+t.status);return t.json()}).then(t=>index=t).catch(t=>{throw loading=null,t})),loading)}self.onmessage=async({data:s})=>{const{id:t,query:a,limit:i,url:l}=s;try{const e=await load(l),c=a.trim().toLowerCase();let n=0,o=[];for(const r of e)(r[1]+" "+r[2]).toLowerCase().includes(c)&&(n++,o.length<i&&o.push(r));self.postMessage({id:t,hits:o,total:n})}catch(e){self.postMessage({id:t,error:String(e.message||e)})}};
